final class CartPanel extends JPanel {             // supply half: model and wiring
    private final CartModel model = new CartModel();
    CartPanel() {
        JLabel total = new JLabel();                // presentational children
        JButton remove = new JButton("Remove");
        remove.addActionListener(e -> model.remove(selected()));
        model.addListener(() -> total.setText(model.total().toString()));
        add(total); add(remove);
    }
}
